time_series_query.prometheus_query:
sum(
    topk(
        10, 
        custom_googleapis_com:volume_read_data{monitored_resource="k8s_cluster",datacenter=~"${Datacenter.value}", cluster=~"${Cluster.value}", svm=~"${SVM.value}", volume=~"${Volume.value}", style!="flexgroup_constituent"} 
        +
        custom_googleapis_com:volume_write_data{monitored_resource="k8s_cluster",datacenter=~"${Datacenter.value}", cluster=~"${Cluster.value}", svm=~"${SVM.value}", volume=~"${Volume.value}", style!="flexgroup_constituent"}
    )
)

(
  custom_googleapis_com:volume_total_ops{monitored_resource="k8s_cluster",datacenter=~"${Datacenter.value}", cluster=~"${Cluster.value}", svm=~"${SVM.value}", volume=~"${Volume.value}",style!="flexgroup_constituent"}
  /
  clamp_min(
    custom_googleapis_com:volume_space_logical_used{monitored_resource="k8s_cluster",datacenter=~"${Datacenter.value}", cluster=~"${Cluster.value}", svm=~"${SVM.value}", volume=~"${Volume.value}",style!="flexgroup_constituent"} / 1099511627776,
    1
  )
)
and
topk(
  10,
  (
    avg_over_time(
      custom_googleapis_com:volume_total_ops{monitored_resource="k8s_cluster",datacenter=~"${Datacenter.value}", cluster=~"${Cluster.value}", svm=~"${SVM.value}", volume=~"${Volume.value}",style!="flexgroup_constituent"}[3h] @ end()
    )
    /
    clamp_min(
      avg_over_time(
        custom_googleapis_com:volume_space_logical_used{monitored_resource="k8s_cluster",datacenter=~"${Datacenter.value}", cluster=~"${Cluster.value}", svm=~"${SVM.value}", volume=~"${Volume.value}",style!="flexgroup_constituent"}[3h] @ end()
      ) / 1099511627776,
      1
    )
  )
  unless
  on(datacenter, cluster, svm, volume)
  volume_labels{monitored_resource="k8s_cluster",datacenter=~"${Datacenter.value}", cluster=~"${Cluster.value}", svm=~"${SVM.value}", volume=~"${Volume.value}", root_volume="Yes",style!="flexgroup_constituent"}
)

(
  custom_googleapis_com:volume_total_ops{monitored_resource="k8s_cluster",datacenter=~"${Datacenter.value}", cluster=~"${Cluster.value}", svm=~"${SVM.value}", volume=~"${Volume.value}",style!="flexgroup_constituent"}
  /
  clamp_min(
    custom_googleapis_com:volume_space_logical_used{monitored_resource="k8s_cluster",datacenter=~"${Datacenter.value}", cluster=~"${Cluster.value}", svm=~"${SVM.value}", volume=~"${Volume.value}",style!="flexgroup_constituent"} / 1099511627776,
    1
  )
)
and
bottomk(
  10,
  (
    avg_over_time(
      custom_googleapis_com:volume_total_ops{monitored_resource="k8s_cluster",datacenter=~"${Datacenter.value}", cluster=~"${Cluster.value}", svm=~"${SVM.value}", volume=~"${Volume.value}",style!="flexgroup_constituent"}[3h] @ end()
    )
    /
    clamp_min(
      avg_over_time(
        custom_googleapis_com:volume_space_logical_used{monitored_resource="k8s_cluster",datacenter=~"${Datacenter.value}", cluster=~"${Cluster.value}", svm=~"${SVM.value}", volume=~"${Volume.value}",style!="flexgroup_constituent"}[3h] @ end()
      ) / 1099511627776,
      1
    )
  )
  and
  on(datacenter, cluster, svm, volume)
  (
    custom_googleapis_com:volume_labels{monitored_resource="k8s_cluster",datacenter=~"${Datacenter.value}", cluster=~"${Cluster.value}", svm=~"${SVM.value}", volume=~"${Volume.value}", root_volume!="Yes",style!="flexgroup_constituent"}
    * on(datacenter, cluster, svm, volume)
    avg_over_time(
      custom_googleapis_com:volume_total_ops{monitored_resource="k8s_cluster",datacenter=~"${Datacenter.value}", cluster=~"${Cluster.value}", svm=~"${SVM.value}", volume=~"${Volume.value}",style!="flexgroup_constituent"}[3h] @ end()
    ) > 50
  )
)
